import unittest


class Carrinho:
    '''Carrinho de compras da loja.'''

    CUPONS = {"PIXEL10": 10, "GAMER25": 25}    # código -> desconto em %

    def __init__(self):
        self.itens = {}        # nome -> [preco, quantidade]
        self.cupom = None

    def adicionar(self, nome, preco, quantidade=1):
        if quantidade < 1:
            raise ValueError("A quantidade deve ser pelo menos 1.")
        if preco < 0:
            raise ValueError("O preço não pode ser negativo.")
        if nome in self.itens:
            self.itens[nome][1] += quantidade
        else:
            self.itens[nome] = [preco, quantidade]

    def remover(self, nome, quantidade=1):
        if nome not in self.itens:
            raise ValueError(f"{nome} não está no carrinho.")
        self.itens[nome][1] -= quantidade
        if self.itens[nome][1] <= 0:
            del self.itens[nome]

    def quantidade(self, nome):
        if nome in self.itens:
            return self.itens[nome][1]
        return 0

    def aplicar_cupom(self, codigo):
        if codigo not in self.CUPONS:
            raise ValueError("Cupom inválido.")
        self.cupom = codigo

    def total(self):
        soma = sum(preco * qtd for preco, qtd in self.itens.values())
        if self.cupom is not None:
            soma = soma * (1 - self.CUPONS[self.cupom] / 100)
        return round(soma, 2)


class TestCarrinho(unittest.TestCase):
    def setUp(self):
        self.carrinho = Carrinho()

    def test_carrinho_novo_tem_total_zero(self):
        self.assertEqual(self.carrinho.total(), 0)

    def test_adicionar_de_novo_soma_a_quantidade(self):
        self.carrinho.adicionar("Poção", 4.5)
        self.carrinho.adicionar("Poção", 4.5, 2)
        self.assertEqual(self.carrinho.quantidade("Poção"), 3)

    def test_total_multiplica_preco_pela_quantidade(self):
        self.carrinho.adicionar("Cavaleiros de Pixel", 59.9)
        self.carrinho.adicionar("Poção", 4.5, 3)
        self.assertAlmostEqual(self.carrinho.total(), 73.4)

    def test_remover_tira_so_a_quantidade_pedida(self):
        self.carrinho.adicionar("Poção", 4.5, 3)
        self.carrinho.remover("Poção", 2)
        self.assertEqual(self.carrinho.quantidade("Poção"), 1)

    def test_remover_a_ultima_unidade_tira_o_item(self):
        self.carrinho.adicionar("Mapa", 12.0)
        self.carrinho.remover("Mapa")
        self.assertEqual(self.carrinho.quantidade("Mapa"), 0)
        self.assertEqual(self.carrinho.total(), 0)

    def test_cupom_desconta_porcentagem(self):
        self.carrinho.adicionar("Cavaleiros de Pixel", 59.9)
        self.carrinho.aplicar_cupom("PIXEL10")
        self.assertAlmostEqual(self.carrinho.total(), 53.91)

    def test_cupom_desconhecido_da_erro(self):
        with self.assertRaises(ValueError):
            self.carrinho.aplicar_cupom("GRATIS100")

    def test_quantidade_zero_da_erro(self):
        with self.assertRaises(ValueError):
            self.carrinho.adicionar("Poção", 4.5, 0)

    def test_preco_negativo_da_erro(self):
        with self.assertRaises(ValueError):
            self.carrinho.adicionar("Poção", -1)

    def test_remover_item_que_nao_esta_no_carrinho_da_erro(self):
        with self.assertRaises(ValueError):
            self.carrinho.remover("Escudo")


if __name__ == "__main__":
    unittest.main(argv=[""], exit=False)
